declare global {
	interface UploadSession {
		id: string;
		created_at: string;
		updated_at: string;
		version: number;
		state?: "open" | "committed" | "deleted";
		expires_at?: string;
		is_expired?: boolean;
		can_mutate?: boolean;
		can_cancel?: boolean;
		can_retry_commit?: boolean;
		publication_configuration_available?: boolean;
		publication_status?: string;
		publication_event_id?: string;
		target_manga?: { id: string; title: string } | null;
		target_status?: string;
		manga_id?: string;
		chapter_id?: string;
		draft?: ChapterDraft | null;
		page_order?: string[];
		committed_result?: Chapter & { publication_status?: string };
		receipt?: Chapter & { publication_status?: string };
		is_committed: bool;
		is_processed: bool;
		is_deleted: bool;
		relationships: {
			manga?: Manga;
			chapter?: Chapter | ChapterDraft;
			uploader?: User;
			groups?: ScanlationGroup[];
			files?: UploadSessionFile[];
		};
	}

	interface UploadSessionFile {
		id: string;
		file_hash: string;
		file_name: string;
		file_ext: string;
		file_size: string;

		original_file_name?: string;
		error?: string;

		file?: File;
		thumbnail?: string;
	}

	interface ChapterDraft {
		volume?: string;
		chapter?: string;
		title?: string;
		language?: string;
	}
}
export {};
